        raise ValueError(f"Invalid duration: {s!r}")

    total_seconds = 0
    pattern = []
    current = ""

    for char in s:
        if char.isdigit():
            current += char
        elif char in ('h', 'm', 's'):
            if not current:
                raise ValueError(f"Invalid duration: {s!r}")
            value = int(current)
            current = ""

            if char == 'h':
                total_seconds += value * 3600
            elif char == 'm':
                total_seconds += value * 60
            elif char == 's':
                total_seconds += value
        else:
            raise ValueError(f"Invalid duration: {s!r}")

    if current:
        raise ValueError(f"Invalid duration: {s!r}")

    return total_seconds
