import re
import urllib.request
import json

# Constants
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'

def task_func(API_URL):
    try:
        with urllib.request.urlopen(API_URL) as response:
            data = json.loads(response.read().decode('utf-8'))
            ip_address = data.get('ip') or data.get('address')

            if not ip_address or not re.fullmatch(IP_REGEX, ip_address):
                raise RuntimeError("API response does not contain a valid public IP address.")

            return str(ip_address)

    except Exception as e:
        return str(e)
```

